/* IELTS interaction prototype only. No server, official test or automatic examiner. */
const STORAGE='latex-ielts-design-v1';
const seed=()=>({role:'student',screen:'practice',appearance:'light',variant:'academic',mode:'single',task:2,answers:{1:'',2:''},scores:{1:[null,null,null,null],2:[null,null,null,null]},notes:{1:['','','',''],2:['','','','']},summary:'',submission:null,published:null,attempt:0,deadline:null,title:'IELTS Writing · Practice 01'});
let model=seed();try{model={...model,...JSON.parse(localStorage.getItem(STORAGE)||'{}')}}catch{}
const $=s=>document.querySelector(s),escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={practice:'Luyện viết IELTS',assignments:'Bài được giao',check:'Kiểm tra và nộp',submitted:'Lịch sử nộp bài',results:'Kết quả & phản hồi',create:'Giao bài IELTS',submissions:'Bài nộp của học viên',grading:'Chấm IELTS Writing',rubric:'Tiêu chí IELTS',admin:'Vận hành'};
const glyph={leaf:'<path d="M11 20A8 8 0 0 1 9.8 4.1C15 3 17 3 19 1c1 2 2 4 2 8 0 6-5 11-10 11ZM2 22c0-6 5-10 12-14"/>',file:'<path d="M14 2H6v20h14V8ZM14 2v6h6M8 13h8M8 17h8"/>',back:'<path d="m12 19-7-7 7-7M5 12h14"/>',review:'<path d="M21 16H7l-5 5V3h19ZM7 7h9M7 11h6"/>',chat:'<path d="M20 15H7l-5 5V3h18ZM9 21h13V8"/>',graduation:'<path d="m2 9 10-5 10 5-10 5ZM6 11v6c3 3 9 3 12 0v-6M22 9v6"/>',help:'<circle cx="12" cy="12" r="10"/><path d="M9 9a3 3 0 0 1 6 1c0 2-3 2-3 4M12 17h.01"/>',history:'<path d="M3 12a9 9 0 1 0 3-7L3 8M3 3v5h5M12 7v5l3 2"/>',layout:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M9 3v18"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${glyph[n]||glyph.file}</svg>`;
const button=(text,action,cls='',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const badge=(text,cls='')=>`<span class="tag ${cls}">${text}</span>`;
const field=(name,html)=>`<label class="field">${name}${html}</label>`;
const count=text=>text.trim()?text.trim().split(/\s+/).length:0;
const tasks=()=>model.mode==='full'?[1,2]:[model.task];
const criterion=(t,variant=model.variant)=>[{code:t===1?'TA':'TR',title:t===1?'Task Achievement':'Task Response',hint:t===1&&variant==='general'?'Đáp ứng mục đích thư, các ý yêu cầu và giọng văn phù hợp.':t===1?'Đáp ứng yêu cầu; lựa chọn thông tin chính và overview phù hợp.':'Trả lời đầy đủ câu hỏi, giữ quan điểm rõ và phát triển lập luận.'},{code:'CC',title:'Coherence & Cohesion',hint:'Tổ chức ý, trình tự đoạn và liên kết phù hợp.'},{code:'LR',title:'Lexical Resource',hint:'Độ đa dạng, chính xác và phù hợp của từ vựng.'},{code:'GRA',title:'Grammatical Range & Accuracy',hint:'Phạm vi cấu trúc câu và độ chính xác ngữ pháp.'}];
const estimate=values=>values.every(v=>v!==null)?values.reduce((a,b)=>a+b,0)/4:null;
const rounded=v=>Math.round(v*2)/2;
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(model))}catch{toast('Không lưu được demo vào trình duyệt. Nội dung hiện vẫn ở bộ nhớ tab.')}}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(window.notice);window.notice=setTimeout(()=>$('#toast').style.display='none',3500)}
function openModal(title,body,action,label){$('#modal-body').innerHTML=`<h2>${title}</h2>${body}<div class="form-actions">${button('Quay lại','close')}${button(label,action,'primary')}</div>`;$('#modal').showModal()}
function go(screen){model.screen=screen;persist();render();$('#main').scrollTop=0}
function header(title,subtitle,actions=''){return `<div class="ielts-head"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="ielts-actions">${actions}</div></div>`}
function taskTabs(scope='active'){return `<div class="task-switch">${[1,2].map(t=>`<button class="${t===model.task?'active':''}" data-task="${t}" data-scope="${scope}">Task ${t}</button>`).join('')}</div>`}
function chart(){return `<div class="prompt-chart"><svg viewBox="0 0 420 238" role="img" aria-label="Biểu đồ tự biên soạn: đi lại bằng ô tô 60 và 45 phần trăm, xe buýt 25 và 30, xe đạp 15 và 25 trong năm 2000 và 2020"><text x="210" y="19" text-anchor="middle" font-size="13" fill="#27382e">Commuting methods in a city (%)</text><path d="M42 42v158h350" stroke="#bdc9c0" fill="none"/>${[0,20,40,60].map(v=>`<text x="32" y="${203-v*2.3}" text-anchor="end" font-size="10" fill="#657267">${v}</text><path d="M42 ${200-v*2.3}h350" stroke="#e4e9e5"/>`).join('')}${[[60,45],[25,30],[15,25]].map((pair,i)=>`<rect x="${70+i*110}" y="${200-pair[0]*2.3}" width="26" height="${pair[0]*2.3}" fill="#216e4b"/><rect x="${100+i*110}" y="${200-pair[1]*2.3}" width="26" height="${pair[1]*2.3}" fill="#9cbda8"/><text x="${98+i*110}" y="219" text-anchor="middle" font-size="11" fill="#27382e">${['Car','Bus','Bicycle'][i]}</text>`).join('')}<rect x="278" y="31" width="9" height="9" fill="#216e4b"/><text x="291" y="39" font-size="10" fill="#27382e">2000</text><rect x="334" y="31" width="9" height="9" fill="#9cbda8"/><text x="347" y="39" font-size="10" fill="#27382e">2020</text></svg><p>Đề và số liệu tự biên soạn để minh họa; không phải đề thi IELTS chính thức.</p></div>`}
function prompt(t=model.task,variant=model.variant){
  if(t===1&&variant==='general')return `<p class="pane-eyebrow">GENERAL TRAINING / TASK 1</p><h2>Letter writing</h2><div class="prompt-meta">${badge('Ít nhất 150 từ')}${badge('Gợi ý 20 phút','gray')}</div><p class="prompt-english">You recently attended a course at a local college. You were pleased with the teaching, but there were some problems with the facilities.</p><p class="prompt-question">Write a letter to the course organiser. Explain what you enjoyed, describe the problems and suggest improvements.</p><p class="prompt-note">Chú ý mục đích, các ý yêu cầu và giọng văn của lá thư.</p>`;
  if(t===1)return `<p class="pane-eyebrow">ACADEMIC / TASK 1</p><h2>Describe & compare data</h2><div class="prompt-meta">${badge('Ít nhất 150 từ')}${badge('Gợi ý 20 phút','gray')}</div><p class="prompt-english">The chart below shows the percentage of commuters using three forms of transport in a city in 2000 and 2020.</p>${chart()}<p class="prompt-question">Summarise the information by selecting and reporting the main features, and make comparisons where relevant.</p>`;
  return `<p class="pane-eyebrow">${variant==='general'?'GENERAL TRAINING':'ACADEMIC'} / TASK 2</p><h2>Discuss both views</h2><div class="prompt-meta">${badge('Ít nhất 250 từ')}${badge('Gợi ý 40 phút','gray')}</div><p class="prompt-english">Some people believe that cities should invest more in public transport, while others think that building more roads is a better way to reduce traffic congestion.</p><p class="prompt-question">Discuss both views and give your own opinion.</p><p class="prompt-note">Give reasons for your answer and include relevant examples from your own knowledge or experience.</p><p class="prompt-note">Đề luyện tự biên soạn, không phải đề thi chính thức.</p>`;
}
function sidebar(){const teacher=model.role==='teacher',admin=model.role==='admin';const links=admin?[['admin','layout','Vận hành']]:teacher?[['create','file','Giao bài IELTS'],['submissions','history','Bài nộp'],['rubric','review','Tiêu chí IELTS']]:[['practice','file','Luyện viết'],['assignments','graduation','Bài được giao'],['submitted','history','Bản nộp'],['results','review','Kết quả']];$('#sidebar').innerHTML=`<div class="sidebar-heading">${icon('graduation')}IELTS Writing</div><div class="side-title">${teacher?'Lớp IELTS · W01':'Practice 01'}<br><small>${teacher?'Nguyễn Minh · Giảng viên':'Trần An · Học viên'}</small></div>${links.map(([id,g,text])=>`<button class="side-link ${model.screen===id?'active':''}" data-route="${id}">${icon(g)}${text}</button>`).join('')}<div class="sidebar-outline"><p class="eyebrow">${teacher?'TIÊU CHÍ CHẤM':'BÀI VIẾT CỦA BẠN'}</p><button data-task="1">Task 1 · ${model.variant==='academic'?'Report':'Letter'}</button><button data-task="2">Task 2 · Essay</button></div><div class="side-note"><strong>${teacher?'Chấm theo 4 tiêu chí IELTS':'Viết trực tiếp bằng tiếng Anh'}</strong>${teacher?'Band học tập và phản hồi theo từng task.':'Không cần LaTeX hoặc compile để nộp bài.'}</div>`}
function practice(){return header('IELTS Writing','Đề bài và câu trả lời trong cùng workspace.',button('Kiểm tra và nộp','check','primary'))+`<div class="ielts-strip">${taskTabs()}<select aria-label="Loại bài IELTS" data-setting="variant"><option value="academic" ${model.variant==='academic'?'selected':''}>Academic</option><option value="general" ${model.variant==='general'?'selected':''}>General Training</option></select><select aria-label="Chế độ luyện" data-setting="mode"><option value="single" ${model.mode==='single'?'selected':''}>Luyện một task</option><option value="full" ${model.mode==='full'?'selected':''}>Đủ hai task · 60 phút</option></select><div class="time-chip"><span id="timer-label">${model.deadline?'Thời gian còn lại':'Chưa bấm giờ'}</span><strong id="timer">${model.mode==='full'?'60:00':model.task===1?'20:00':'40:00'}</strong>${button(model.deadline?'Đặt lại':'Bắt đầu','timer')}</div></div><div class="ielts-body"><section class="prompt-pane">${prompt()}<details class="study-guidance"><summary>4 tiêu chí được chấm</summary>${criterion(model.task).map(c=>`<p><strong>${c.code} · ${c.title}</strong><br>${c.hint}</p>`).join('')}<p>Gợi ý học tập; không thay band descriptors chính thức.</p></details></section><section class="answer-pane"><div class="answer-top"><span class="answer-name">${icon('file')}Task ${model.task} · Your answer</span><span class="saved" id="save-state">✓ Đã lưu demo</span></div><div class="answer-sheet"><textarea id="answer" aria-label="Bài viết Task ${model.task}" spellcheck="false" placeholder="Write your answer here…\n\nBạn viết bài bằng tiếng Anh ngay tại đây. Không cần viết mã LaTeX.">${escape(model.answers[model.task])}</textarea></div><div class="answer-status"><span id="word-count">${wordStatus()}</span><span>Văn bản · không tính đề bài</span></div><div class="small-info">Luyện tập cá nhân · đồng hồ chỉ mô phỏng trên browser · nộp bài không cần compile PDF</div></section></div>`}
function wordStatus(){const n=count(model.answers[model.task]),min=model.task===1?150:250;return `<strong>${n} từ</strong> <span class="${n<min?'word-warning':'word-ok'}">/ tối thiểu ${min} · ${n<min?'Còn '+(min-n)+' từ':'Đã đạt số từ khuyến nghị tối thiểu'}</span>`}
function list(){return header('Bài được giao','Luyện IELTS theo task; bài thi thử đầy đủ tách thành chế độ riêng.')+`<div class="ielts-page"><div class="card table-card"><table><thead><tr><th>Bài tập</th><th>Dạng bài</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr><td><strong>${escape(model.title)}</strong><small>Giảng viên Nguyễn Minh · cá nhân</small></td><td>${model.variant==='academic'?'Academic':'General Training'} · ${model.mode==='full'?'Hai task':'Task '+model.task}</td><td>${badge(model.submission?'Đã nộp':'Đang làm')}</td><td>${button('Tiếp tục viết','practice','primary')}</td></tr></tbody></table></div></div>`}
function check(){const required=tasks(),empty=required.some(t=>!model.answers[t].trim());return header('Kiểm tra bài IELTS','Kiểm tra task và số từ; không cần chuyển qua LaTeX.',button('Quay lại viết','practice')+button('Xác nhận nộp','submit-dialog','primary',empty?'disabled':''))+`<div class="ielts-page">${empty?'<div class="ielts-notice">Cần có nội dung cho tất cả task được giao trước khi nộp.</div>':''}${required.map(t=>`<section class="ielts-submit-task"><div class="page-head"><h3>Task ${t}</h3>${badge(`${count(model.answers[t])} / ${t===1?150:250} từ`,count(model.answers[t])<(t===1?150:250)?'amber':'')}</div><p class="reading-answer ${model.answers[t]?'':'empty-answer'}">${escape(model.answers[t]||'Chưa có bài viết.')}</p></section>`).join('')}<p class="prompt-note">Bài thiếu từ được cảnh báo, không tự trừ band hoặc chặn giảng viên chấm. Bản nộp được đóng băng trong demo; bạn vẫn có thể sửa bản làm việc riêng.</p></div>`}
function submitted(){const s=model.submission;return header('Lịch sử nộp bài','Bản nộp giữ riêng với working copy.',button('Tiếp tục luyện','practice'))+(s?`<div class="ielts-page"><div class="ielts-notice">✓ Đã nộp trong demo · Lần ${s.attempt} · ${escape(s.at)} · ${s.tasks.map(t=>'Task '+t).join(' + ')}. ${model.published?'Đã có phản hồi.':'Chờ giảng viên chấm và công bố.'}</div>${s.tasks.map(t=>`<div class="ielts-submit-task"><h3>Task ${t} · ${count(s.answers[t])} từ</h3><div class="reading-answer">${escape(s.answers[t])}</div></div>`).join('')}</div>`:`<div class="practice-empty"><h2>Chưa có bản nộp</h2><p>Viết bài IELTS, kiểm tra và gửi cho giảng viên.</p>${button('Vào luyện viết','practice','primary')}</div>`)}
function submissions(){return header('Bài nộp IELTS','Chấm từng học viên theo task, không chấm theo nhóm nghiên cứu.',button('Giao bài mới','create','primary'))+`<div class="ielts-page"><div class="card table-card"><table><thead><tr><th>Học viên</th><th>Bài nộp</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr><td><strong>Trần An</strong><small>Lớp W01</small></td><td>${model.submission?model.submission.tasks.map(t=>'Task '+t).join(' + '):'Chưa nộp'}</td><td>${badge(model.published?'Đã công bố':model.submission?'Chờ chấm':'Đang làm',model.submission?'':'amber')}</td><td>${button('Chấm bài','grade','primary',model.submission?'':'disabled')}</td></tr></tbody></table></div><p class="note">Chuyển vai trò Học viên để thử viết và nộp một bài; không có bài nghiên cứu hoặc điểm 10 trong luồng này.</p></div>`}
function bandCard(c,i){const score=model.scores[model.task][i];return `<section class="band-card"><div class="band-row"><strong>${c.code}<span>${c.title}</span></strong><select aria-label="Band ${c.code}" data-score="${i}"><option value="">—</option>${Array.from({length:19},(_,n)=>n/2).map(v=>`<option value="${v}" ${score===v?'selected':''}>${v.toFixed(1)}</option>`).join('')}</select></div><details><summary>Gợi ý đánh giá</summary><p>${c.hint}</p><p>Diễn giải phục vụ luyện tập, không phải nguyên văn band descriptors.</p></details><details class="criterion-feedback"><summary>Feedback</summary><textarea aria-label="Nhận xét ${c.code}" data-note="${i}" placeholder="Nhận xét cụ thể, ví dụ từ bài viết…">${escape(model.notes[model.task][i])}</textarea></details></section>`}
function grading(){const s=model.submission;if(!s)return header('Chấm IELTS Writing','Chưa có bài nộp.')+`<div class="practice-empty"><h2>Học viên chưa nộp bài</h2>${button('Danh sách bài nộp','submissions')}</div>`;if(!s.tasks.includes(model.task))model.task=s.tasks[0];return header('Chấm IELTS Writing',`Trần An · lần ${s.attempt} · ${s.variant==='academic'?'Academic':'General Training'}`,button('Lưu nháp','grade-save')+button('Công bố phản hồi','publish-dialog','primary'))+`<div class="ielts-strip">${s.tasks.map(t=>`<button class="${model.task===t?'primary':''}" data-task="${t}" data-scope="grade">Task ${t}</button>`).join('')}<span>${badge('Nháp · học viên chưa thấy điểm','amber')}</span><span class="time-chip">${count(s.answers[model.task])} từ · bản nộp chỉ đọc</span></div><div class="ielts-grade-layout"><aside class="grade-roster"><p class="pane-eyebrow">HỌC VIÊN</p><button class="submission-item active">Trần An<small>Lần nộp ${s.attempt}</small>${badge(model.published?'Đã trả':'Đang chấm')}</button></aside><section class="grade-response"><div class="prompt-summary">Task ${model.task} · ${model.task===2?'Discuss both views and give your opinion.':s.variant==='academic'?'Describe and compare the chart.':'Write a letter to the organiser.'}</div><div class="reading-answer">${escape(s.answers[model.task])}</div></section><aside class="assessment-pane"><h2>4 tiêu chí IELTS</h2>${criterion(model.task,s.variant).map(bandCard).join('')}<div class="band-summary"><div>Task ${model.task} band<small>Ước tính luyện tập · chưa đủ điểm sẽ để trống</small></div><strong id="task-band">${taskBandText()}</strong></div>${field('Nhận xét chung',`<textarea id="summary" rows="3" placeholder="Điểm mạnh và việc nên luyện tiếp…">${escape(model.summary)}</textarea>`)}<p class="ielts-band-note">Mỗi tiêu chí cùng trọng số trong task. Tổng Writing chỉ tính khi có đủ hai task; Task 2 có trọng số gấp đôi. Đây không phải điểm thi được chứng nhận.</p></aside></div>`}
function taskBandText(){const n=estimate(model.scores[model.task]);return n===null?'—':rounded(n).toFixed(1)}
function results(){const p=model.published;return header('Kết quả & phản hồi','Band luyện tập do giảng viên đánh giá; không phải kết quả thi IELTS chính thức.',button('Về luyện viết','practice'))+(!p?`<div class="practice-empty"><h2>Chưa có kết quả được công bố</h2><p>Điểm chấm nháp không xuất hiện ở màn hình học viên.</p></div>`:`<div class="ielts-page"><div class="result-hero"><div><p class="pane-eyebrow">TRẦN AN · LẦN NỘP ${p.attempt}</p><h2>${p.tasks.length===2?'Writing band ước tính':'Task '+p.tasks[0]+' band ước tính'}</h2><p class="subtle">${p.tasks.length===2?'Tổng hợp từ hai task, trọng số 1 : 2.':'Chỉ có một task, không gọi đây là Overall Writing.'}</p></div><strong class="band-number">${p.band.toFixed(1)}</strong></div>${p.tasks.map(t=>`<h2>Task ${t} · ${rounded(estimate(p.scores[t])).toFixed(1)}</h2><div class="band-breakdown">${criterion(t,p.variant).map((c,i)=>`<div><small>${c.code} · ${c.title}</small><strong>${p.scores[t][i].toFixed(1)}</strong></div>`).join('')}</div><div class="feedback-list">${criterion(t,p.variant).map((c,i)=>`<section><h3>${c.code} · ${c.title}</h3><p>${escape(p.notes[t][i]||'Giảng viên chưa thêm nhận xét riêng cho tiêu chí này.')}</p></section>`).join('')}</div><details class="study-guidance"><summary>Xem lại bài nộp Task ${t}</summary><div class="reading-answer">${escape(p.answers[t])}</div></details>`).join('')}<div class="ielts-notice"><strong>Gợi ý luyện tiếp</strong><br>${escape(p.summary)}</div>${button('Xuất phiếu PDF / LaTeX (thiết kế)','export')}<p class="ielts-band-note">Làm tròn tới 0.5 là chính sách demo; lưu cả điểm gốc trước khi làm tròn khi triển khai thật.</p></div>`)}
function rubric(){return header('Tiêu chí IELTS Writing','Bộ 4 tiêu chí cố định; checklist giúp nhận xét, không cộng điểm kiểu bài nghiên cứu.')+`<div class="ielts-strip">${taskTabs('rubric')}</div><div class="ielts-page"><div class="feedback-list">${criterion(model.task).map(c=>`<section><h3>${c.code} · ${c.title}</h3><p>${c.hint}</p><p>Giảng viên nhập band, nhận xét và dẫn chứng theo bài viết. Chưa chấm là null, khác band 0.</p></section>`).join('')}</div><div class="ielts-notice">Band 0–9 phục vụ đánh giá học tập. Không có tiêu chí “Khoảng trống nghiên cứu”, không cộng điểm /10, không tự chấm band chỉ dựa số từ.</div><p class="reference-link"><a href="https://ielts.org/take-a-test/test-types/ielts-academic-test/ielts-academic-format-writing" target="_blank" rel="noopener">Đối chiếu định dạng Writing trên IELTS.org ↗</a></p></div>`}
function create(){return header('Giao bài IELTS','Cá nhân là mặc định; chọn rõ một task hoặc đầy đủ hai task.',button('Lưu đề nháp','draft')+button('Giao bài','assign-dialog','primary'))+`<div class="ielts-page"><div class="assignment-form"><div class="card"><h2>1. Cấu hình bài luyện</h2>${field('Tên bài',`<input data-setting="title" value="${escape(model.title)}">`)}<div class="form-grid">${field('Loại bài',`<select data-setting="variant"><option value="academic" ${model.variant==='academic'?'selected':''}>Academic</option><option value="general" ${model.variant==='general'?'selected':''}>General Training</option></select>`)}${field('Phạm vi',`<select data-setting="mode"><option value="single" ${model.mode==='single'?'selected':''}>Một task</option><option value="full" ${model.mode==='full'?'selected':''}>Task 1 + Task 2</option></select>`)}</div><p class="subtle">Task 1: biểu đồ/bảng/process/map cho Academic hoặc thư cho General Training. Task 2: essay.</p></div><div class="card"><h2>2. Đề bài & tài liệu</h2><p class="subtle">Prototype dùng hai đề tự biên soạn. Nhập đề và upload ảnh sẽ được nối backend khi triển khai.</p>${prompt(model.task)}</div><div class="card"><h2>3. Giao bài & phản hồi</h2><p>Lớp W01 · học viên Trần An · làm cá nhân.</p><p class="subtle">Policy thật sẽ có hạn nộp, thời lượng tùy chọn và số lần nộp. Không mặc định luyện nhóm hay bắt viết LaTeX.</p>${button('Xem tiêu chí IELTS','rubric')}</div></div></div>`}
function render(){document.documentElement.dataset.mode=model.appearance;sidebar();$('#role').value=model.role;$('#avatar').textContent=model.role==='teacher'?'GV':model.role==='student'?'HV':'AD';const allowed=model.role==='teacher'?['create','submissions','grading','rubric']:model.role==='admin'?['admin']:['practice','assignments','check','submitted','results'];$('#screen-map').innerHTML=allowed.map(s=>`<option value="${s}" ${s===model.screen?'selected':''}>${labels[s]}</option>`).join('');$('#screen-label').textContent=`IELTS Writing · ${labels[model.screen]||'Luyện tập'}`;const views={practice,assignments:list,check,submitted,results,submissions,grading,rubric,create,admin:()=>header('Vận hành IELTS Writing','Thiết kế: tài khoản, phân quyền giáo viên/học viên và bài nộp riêng.')+'<div class="ielts-notice">Đây là mock-up. Vai trò, session, thời gian nộp và quyền xem điểm phải kiểm tra trên server khi triển khai.</div>'};$('#main').innerHTML=(views[model.screen]||practice)();document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));updateTimer()}
function updateTimer(){if(!$('#timer'))return;if(!model.deadline)return;const seconds=Math.max(0,Math.ceil((model.deadline-Date.now())/1000));$('#timer').textContent=`${Math.floor(seconds/60).toString().padStart(2,'0')}:${(seconds%60).toString().padStart(2,'0')}`;$('#timer-label').textContent=seconds?'Thời gian còn lại':'Đã hết giờ (demo)';$('#timer').parentElement.classList.toggle('expired',!seconds)}
setInterval(updateTimer,1000);
document.addEventListener('input',e=>{const el=e.target;if(el.id==='answer'){model.answers[model.task]=el.value;persist();$('#word-count').innerHTML=wordStatus();$('#save-state').textContent='✓ Đã lưu demo';}if(el.dataset.note!==undefined){model.notes[model.task][+el.dataset.note]=el.value;persist()}if(el.id==='summary'){model.summary=el.value;persist()}if(el.dataset.setting==='title'){model.title=el.value;persist()}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='role'){model.role=el.value;go(model.role==='teacher'?'submissions':model.role==='admin'?'admin':'practice')}if(el.id==='screen-map')go(el.value);if(el.dataset.setting&&el.dataset.setting!=='title'){model[el.dataset.setting]=el.value;model.deadline=null;persist();render()}if(el.dataset.score!==undefined){model.scores[model.task][+el.dataset.score]=el.value===''?null:Number(el.value);persist();$('#task-band').textContent=taskBandText()}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el||el.disabled)return;if(el.dataset.route){go(el.dataset.route);return}if(el.dataset.task){if(model.task!==+el.dataset.task&&model.mode==='single'&&model.deadline){model.deadline=null;toast('Đổi task: đã đặt lại đồng hồ luyện.')}model.task=+el.dataset.task;if(!['grading','rubric','practice'].includes(model.screen))model.screen=model.role==='teacher'?'rubric':'practice';persist();render();return}const a=el.dataset.action;if(['practice','check','submitted','submissions','rubric','create'].includes(a)){go(a);return}switch(a){
case'grade':model.task=model.submission.tasks[0];go('grading');break;
case'timer':if(model.deadline){openModal('Đặt lại đồng hồ demo?','<p>Đồng hồ chỉ mô phỏng luyện tập trên máy này, không phải thời gian do server xác nhận.</p>','timer-reset','Đặt lại');}else{model.deadline=Date.now()+(model.mode==='full'?60:model.task===1?20:40)*60000;persist();render()}break;
case'timer-reset':model.deadline=null;persist();$('#modal').close();render();break;
case'submit-dialog':{const short=tasks().some(t=>count(model.answers[t])<(t===1?150:250));openModal('Nộp bài IELTS?',`<p>${tasks().map(t=>'Task '+t).join(' + ')} · Trần An · lần ${model.attempt+1}</p>${short?'<p class="word-warning">Bài chưa đủ số từ tối thiểu. Bạn có thể quay lại bổ sung hoặc vẫn nộp để nhận phản hồi.</p>':''}<p>Đây là nộp bài demo. Không cần chuyển LaTeX hoặc compile PDF.</p>`,'submit','Xác nhận nộp');break;}
case'submit':model.attempt++;model.submission={tasks:[...tasks()],answers:{...model.answers},variant:model.variant,attempt:model.attempt,at:new Date().toLocaleString('vi-VN')};model.scores={1:[null,null,null,null],2:[null,null,null,null]};model.notes={1:['','','',''],2:['','','','']};model.summary='';model.published=null;persist();$('#modal').close();go('submitted');break;
case'publish-dialog':{const s=model.submission;if(!s||s.tasks.some(t=>estimate(model.scores[t])===null)){toast('Cần chấm đủ 4 tiêu chí cho từng task đã nộp.');break}if(!model.summary.trim()){toast('Vui lòng nhập nhận xét chung.');break}openModal('Công bố phản hồi?',`<p>Học viên Trần An sẽ thấy band và nhận xét của các task đã nộp.</p><p>Đây là band ước tính luyện tập, không phải chứng nhận IELTS.</p>`,'publish','Công bố');break;}
case'publish':{const s=model.submission,raw=s.tasks.length===2?(estimate(model.scores[1])+2*estimate(model.scores[2]))/3:estimate(model.scores[s.tasks[0]]);model.published=JSON.parse(JSON.stringify({...s,scores:model.scores,notes:model.notes,summary:model.summary,rawBand:raw,band:rounded(raw)}));persist();$('#modal').close();toast('Đã công bố demo. Chuyển Học viên → Kết quả.');render();break;}
case'grade-save':persist();toast('Đã lưu chấm nháp demo. Học viên chưa xem được điểm.');break;
case'appearance':model.appearance=model.appearance==='light'?'dark':'light';persist();document.documentElement.dataset.mode=model.appearance;break;
case'close':$('#modal').close();break;
case'reset':openModal('Reset prototype IELTS?','<p>Chỉ xóa dữ liệu demo IELTS ở trình duyệt. Không ảnh hưởng ứng dụng hoặc bài viết thật.</p>','reset-confirm','Reset demo');break;
case'reset-confirm':model=seed();persist();$('#modal').close();render();break;
case'assign-dialog':openModal('Giao bài IELTS?',`<p>${escape(model.title)} · lớp W01 · làm cá nhân.</p><p>Prototype không gửi thông báo hoặc ghi lên server.</p>`,'assigned','Giao bài');break;
case'assigned':$('#modal').close();go('submissions');toast('Đã mô phỏng giao bài.');break;
case'draft':persist();toast('Đã lưu đề nháp demo.');break;
case'export':toast('PDF/LaTeX là xuất phiếu sau chấm, không bắt buộc khi làm bài. Prototype không tạo file giả.');break;
case'help':openModal('Thử thiết kế IELTS Writing','<ol><li>Chọn Task 1 hoặc Task 2, viết câu trả lời.</li><li>Kiểm tra số từ → nộp trực tiếp.</li><li>Đổi Giảng viên → chấm đủ bốn tiêu chí → công bố.</li><li>Đổi Học viên → Kết quả.</li></ol><p>Chọn đủ hai task nếu muốn thử Writing band tổng hợp. Bản mẫu không chấm tự động hoặc kết nối server.</p>','close','Đã hiểu');break;
case'editor':case'history':case'layout':case'participants':case'review':case'chat':toast('Nút giữ vị trí của workspace chính; thiết kế IELTS tập trung vào đề, bài viết và phản hồi cá nhân.');break;
}});
render();
